# taille: CSS size of the icon (1em: the size of the text around it).
icone <- function(nom, taille = "1em") {
  htmltools::HTML(gsub("height:1em;width:1em", sprintf("height:%s;width:%s", taille, taille),
                       ICONES[[nom]], fixed = TRUE))
}
